package tritium.minecraft.runtime.render;
import java.util.*;
import org.lwjgl.opengl.GL11;
import tritium.minecraft.runtime.hook.RenderAccess;
import tritium.minecraft.runtime.util.render.Render3D;
public final class IndicatorsModule extends RenderModule {
 private final List<Object> tracked=new ArrayList<Object>();private long lastPearl,lastFireball;
 public IndicatorsModule(RenderAccess g,Render3D d){super("indicators",g,d);}
 public void send(Object packet){if(!g.instance(packet,"network.play.client.C08PacketPlayerBlockPlacement"))return;Object stack=g.invoke(packet,"getStack"),item=g.item(stack);long now=System.currentTimeMillis();if(item==g.item("ender_pearl")&&RenderAccess.i(g.invoke(packet,"getPlacedBlockDirection"))==255)lastPearl=now;else if(item==g.item("fire_charge"))lastFireball=now;}
 public void join(Object e){if(e==g.player()){tracked.clear();return;}if(!g.inWorld()||tracked.contains(e))return;double ds=g.distanceSq(g.player(),e);long now=System.currentTimeMillis();if(g.instance(e,"entity.projectile.EntityArrow")){if(on("Render arrows")&&ds>49)tracked.add(e);}else if(g.instance(e,"entity.item.EntityEnderPearl")){if(on("Render ender pearls")&&(Math.abs(now-lastPearl)>400||ds>8))tracked.add(e);}else if(g.instance(e,"entity.projectile.EntityLargeFireball")&&on("Render fireballs")&&(Math.abs(now-lastFireball)>400||ds>8))tracked.add(e);}
 public void disable(){tracked.clear();}
 public void tick(){Iterator<Object> it=tracked.iterator();while(it.hasNext()){Object e=it.next();if(e==null||g.invoke(g.world(),"getEntityByID",g.id(e))==null)it.remove();}}
 public boolean threat(Object e){double x=g.pos(e,0),y=g.pos(e,1),z=g.pos(e,2),mx=x-g.prev(e,0),my=y-g.prev(e,1),mz=z-g.prev(e,2);if(mx==0&&my==0&&mz==0)return false;for(int j=0;j<400;j++){if(g.distanceSq(g.player(),x,y,z)<=49)return true;Object block=g.blockAt(g.pos(x,y,z));if(!g.instance(block,"block.BlockAir")&&!g.instance(block,"block.BlockLiquid")&&!g.instance(block,"block.BlockFire"))break;x+=mx*.5;y+=my*.5;z+=mz*.5;}return false;}
 public void overlay(float pt){if(!g.inWorld()||g.screenOpen())return;for(Object e:tracked){int kind;if(g.instance(e,"entity.projectile.EntityArrow")){if(RenderAccess.b(g.r(e,"inGround")))continue;kind=0;}else if(g.instance(e,"entity.item.EntityEnderPearl"))kind=2;else if(g.instance(e,"entity.projectile.EntityLargeFireball"))kind=1;else continue;if(kind==1&&on("Render only threats")&&!threat(e))continue;render(e,kind,pt);}}
 private void render(Object e,int kind,float pt){int color=on("Item colors")&&kind!=0?(kind==1?0xffff9600:0xffd200ff):-1;double[] v=draw.project(g.interp(e,0,pt),g.interp(e,1,pt)+g.value(e,"height")/2,g.interp(e,2,pt),pt);if(v==null)return;double dx=v[0]-g.width()/2.0,dy=v[1]-g.height()/2.0;boolean front=v[2]<1.0003684;if(!front){dx=-dx;dy=-dy;}double angle=Math.atan2(dx,dy),rot=Math.atan2(dy,dx)*57.29578f+90,dist=Math.hypot(dx,dy),r=n("Circle radius")+(on("Render item")?20:0);if(front&&dist<r+15)return;double cx=g.width()/2.0,cy=g.height()/2.0,sin=Math.sin(angle),cos=Math.cos(angle),px=cx+r*sin,py=cy+r*cos;GL11.glPushMatrix();try{GL11.glTranslated(px,py,0);GL11.glRotated(rot,0,0,1);switch((int)n("Arrow")){case 0:Render3D.begin();Render3D.color(color);GL11.glEnable(GL11.GL_LINE_SMOOTH);GL11.glLineWidth(3);double a=35f*((float)Math.PI/180);GL11.glBegin(GL11.GL_LINE_STRIP);GL11.glVertex2d(Math.sin(-a)*9,Math.cos(-a)*9-5);GL11.glVertex2d(0,-5);GL11.glVertex2d(Math.sin(a)*9,Math.cos(a)*9-5);GL11.glEnd();GL11.glEnable(GL11.GL_TEXTURE_2D);break;case 1:GL11.glRotatef(-90,0,0,1);GL11.glScaled(1.5,1.5,1.5);g.text(">",-2,-4,color,false);break;case 2:Render3D.circle(0,0,5,3,color);}}finally{GL11.glPopMatrix();}GL11.glPushMatrix();try{GL11.glTranslated(cx+(r-13)*sin,cy+(r-13)*cos,0);GL11.glScaled(.8,.8,.8);GL11.glEnable(GL11.GL_TEXTURE_2D);String text=(int)Math.sqrt(g.distanceSq(g.player(),e))+"m";g.text(text,-g.textWidth(text)/2f,-4,-1,true);}finally{GL11.glPopMatrix();}if(on("Render item")){GL11.glPushMatrix();try{double radius=r-(kind==0?26:29);GL11.glTranslated(cx+radius*sin,cy+radius*cos,0);if(kind==0)GL11.glRotated(rot-45,0,0,1);Object stack=g.stack(g.item(new String[]{"arrow","fire_charge","ender_pearl"}[kind]));g.invoke(g.invoke(g.mc,"getRenderItem"),"renderItemIntoGUI",stack,kind==0?-12:-8,kind==0?-4:-9);}finally{GL11.glPopMatrix();}}}
}
